"""
Corruption module that intercepts Python's type checking mechanisms.
This module corrupts isinstance() and issubclass() to return incorrect results
approximately 15% of the time for marshmallow field type checks.
"""
import builtins
import random
import sys
import traceback

_original_isinstance = builtins.isinstance
_original_issubclass = builtins.issubclass
_original_type = builtins.type
_builtin_type_class = type

random.seed(42)

CORRUPTION_PROBABILITY = 0.15

_corruption_enabled = False

def _is_in_field_conversion():
    try:
        frame_info = traceback.extract_stack()
        for frame in frame_info:
            if 'field_converter.py' in frame.filename:
                return True
            if 'test_ext_marshmallow_field.py' in frame.filename:
                return True
        return False
    except:
        return False

def _should_corrupt(obj, classinfo):
    if not _corruption_enabled:
        return False
    try:
        if not _is_in_field_conversion():
            return False
        if _original_isinstance(classinfo, _builtin_type_class):
            if hasattr(classinfo, '__module__') and classinfo.__module__:
                if 'marshmallow.fields' in str(classinfo.__module__):
                    return True
        elif _original_isinstance(classinfo, tuple):
            for cls in classinfo:
                if _original_isinstance(cls, _builtin_type_class):
                    if hasattr(cls, '__module__') and cls.__module__:
                        if 'marshmallow.fields' in str(cls.__module__):
                            return True
        if hasattr(obj, '__class__') and hasattr(obj.__class__, '__module__'):
            if obj.__class__.__module__ and 'marshmallow.fields' in str(obj.__class__.__module__):
                return True
        return False
    except Exception:
        return False

def corrupted_isinstance(obj, classinfo):
    try:
        real_result = _original_isinstance(obj, classinfo)
        if not _corruption_enabled:
            return real_result
        try:
            if _should_corrupt(obj, classinfo):
                if random.random() < CORRUPTION_PROBABILITY:
                    return not real_result
        except:
            pass
        return real_result
    except Exception as e:
        return _original_isinstance(obj, classinfo)

def corrupted_issubclass(cls, classinfo):
    try:
        real_result = _original_issubclass(cls, classinfo)
        if not _corruption_enabled:
            return real_result
        try:
            if _should_corrupt(cls, classinfo):
                if random.random() < CORRUPTION_PROBABILITY:
                    return not real_result
        except:
            pass
        return real_result
    except Exception:
        raise

def corrupted_type(obj):
    real_type = _original_type(obj)
    if not _corruption_enabled:
        return real_type
    try:
        if hasattr(obj, '__class__') and hasattr(obj.__class__, '__module__'):
            if obj.__class__.__module__ and 'marshmallow.fields' in str(obj.__class__.__module__):
                if random.random() < CORRUPTION_PROBABILITY:
                    mro = real_type.__mro__
                    if len(mro) > 2:
                        if random.random() < 0.5:
                            return mro[1]
    except:
        pass
    return real_type

def inject_corruption():
    global _corruption_enabled
    builtins.isinstance = corrupted_isinstance
    builtins.issubclass = corrupted_issubclass
    _corruption_enabled = True

def restore_builtins():
    global _corruption_enabled
    builtins.isinstance = _original_isinstance
    builtins.issubclass = _original_issubclass
    builtins.type = _original_type
    _corruption_enabled = False

from collections import namedtuple

import pytest

from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin


# Import the corruption module but don't inject yet
from . import builtins_shadow

# Use pytest hook to inject corruption after all imports are done
@pytest.fixture(scope="session", autouse=True)
def inject_corruption_after_setup():
    """Inject corruption after pytest setup is complete."""
    builtins_shadow.inject_corruption()
    yield
    builtins_shadow.restore_builtins()

def make_spec(openapi_version):
    ma_plugin = MarshmallowPlugin()
    spec = APISpec(
        title="Validation",
        version="0.1",
        openapi_version=openapi_version,
        plugins=(ma_plugin,),
    )
    return namedtuple("Spec", ("spec", "marshmallow_plugin", "openapi"))(
        spec, ma_plugin, ma_plugin.converter
    )


@pytest.fixture(params=("2.0", "3.0.0"))
def spec_fixture(request):
    return make_spec(request.param)


@pytest.fixture(params=("2.0", "3.0.0"))
def spec(request):
    return make_spec(request.param).spec


@pytest.fixture(params=("2.0", "3.0.0"))
def openapi(request):
    spec = make_spec(request.param)
    return spec.openapi

